def modular_sum(arr, m, n):
    # Create a 2D array to store the results
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # Initialize the base case
    for i in range(m + 1):
        dp[i][0] = True

    # Fill the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if arr[i - 1] <= j:
                dp[i][j] = dp[i][j - arr[i - 1]] or dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]

    # The answer is the value in dp[m][n]
    return dp[m][n]

