    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                lis[i][j] = lis[j][i] + 1
            elif arr[i] < arr[j]:
                dls[i][j] = dls[j][i] + 1

    # The maximum value in the LIS array is the length of the longest increasing subsequence
    longest_increasing = max(lis)

    # Initialize the result with the length of the longest increasing subsequence
    result = longest_increasing

    # Check if there is a decreasing subsequence in the same position
    for i in range(n):
        if dls[i][i] > longest_increasing:
            result = max(result, dls[i][i])

    return result

