    for i in range(1, len(arr)):
        # Compare the current element with the previous one
        if arr[i] > arr[i - 1]:
            # Update the DP table for the current element
            dp[i] = dp[i - 1] + 1

        # Update the DP table for the previous element
        if arr[i] < arr[i - 1]:
