    for i in range(n):
        for j in range(n):
            for k in range(i+1, n):
                for l in range(j+1, n):
                    path_sum = matrix[i][j] + matrix[k][l] + matrix[i][k] + matrix[k][j]
                    path_length = 4
                    path_avg = path_sum / path_length
                    if path_avg > max_avg:
                        max_avg = path_avg
    return max_avg

