def sort_by_dnf(arr, n):
    # Use a set to track indices of 0s
    zeros = set()
    # Use a list to store the remaining elements
    remaining = []

    # Iterate through the array
    for i in range(n):
        # If the element is 0, add its index to the set of zeros
        if arr[i] == 0:
            zeros.add(i)
        # If the element is 1, add it to the list
        else:
            remaining.append(arr[i])

    # Sort the list of remaining elements in their original order
    remaining.sort()

    # Replace the original elements with the sorted elements
    for i in range(n):
        if arr[i] == 0:
            arr[i] = remaining[zeros.pop(0)]
        else:
            arr[i] = remaining[zeros.pop()]

    return arr

