def second_frequent(sequence):
    # Step 1: Count the frequency of each string in the sequence
    frequency_dict = {}
    for string in sequence:
        if string in frequency_dict:
            frequency_dict[string] += 1
        else:
            frequency_dict[string] = 1

    # Step 2: Sort the dictionary by frequency in descending order
    sorted_frequencies = sorted(frequency_dict.items(), key=lambda x: x[1], reverse=True)

    # Step 3: Check if there are at least two unique strings
