def nth_super_ugly_number(k, primes):
    heap = []
    for prime in primes:
        heapq.heappush(heap, prime)
    ugly = []
    while len(ugly) < k:
        current = heapq.heappop(heap)
        ugly.append(current)
        for prime in primes:
            if current * prime <= ugly[-1]:
                heapq.heappush(heap, current * prime)
    return ugly[-1]

